class RawCDPPublishAdapter:
    def __init__(self, runner: NodeCDPRunner):
        self.runner = runner

    def observe_private_upload(
        self,
        remote_channel_id: str,
        package: SealedContentPackage,
    ) -> PublishObservation:
        title = str(package.metadata.get("title") or "").strip()
        if not title:
            return PublishObservation("UNCERTAIN", evidence={"reason": "sealed title missing"})
        result = self.runner.run(
            "PUBLISH_OBSERVE",
            CHANNEL_ID=remote_channel_id,
            VIDEO_TITLE=title,
        )
        state = str(result.get("state") or "UNCERTAIN")
        return PublishObservation(
            state,
            remote_video_id=result.get("remote_video_id"),
            visibility=result.get("visibility"),
            evidence={
                "candidate_count": result.get("candidate_count"),
                "link_count": result.get("link_count"),
                "reason": result.get("reason"),
                "source": "studio-content-readback",
            },
        )

    def dispatch_private_upload(
        self,
        remote_channel_id: str,
        package: SealedContentPackage,
    ) -> None:
        result = self.runner.run(
            "PUBLISH_PRIVATE",
            CHANNEL_ID=remote_channel_id,
            ASSET_PATH=package.asset_path,
            VIDEO_TITLE=str(package.metadata.get("title") or ""),
            VIDEO_DESCRIPTION=str(package.metadata.get("description") or ""),
            MADE_FOR_KIDS="1" if bool(package.metadata.get("made_for_kids")) else "0",
        )
        if result.get("state") != "PRIVATE_UPLOAD_DISPATCHED":
            raise RawCDPAdapterError(str(result.get("state") or "private upload stopped"))

    def observe_thumbnail(
        self,
        remote_channel_id: str,
        remote_video_id: str,
        package: SealedContentPackage,
    ) -> ThumbnailObservation:
        result = self.runner.run(
            "THUMBNAIL_OBSERVE",
            CHANNEL_ID=remote_channel_id,
            VIDEO_ID=remote_video_id,
        )
        state = str(result.get("state") or "UNKNOWN")
        return ThumbnailObservation(
            persisted=state == "THUMBNAIL_OBSERVED" and bool(result.get("persisted")),
            token=str(result.get("token") or "").strip() or None,
            evidence={
                "state": state,
                "surface_ready": bool(result.get("surface_ready")),
                "source": "fresh-exact-video-editor-readback",
                "reason": result.get("reason"),
            },
        )

    def dispatch_thumbnail(
        self,
        remote_channel_id: str,
        remote_video_id: str,
        package: SealedContentPackage,
    ) -> None:
        if not package.thumbnail_path:
            raise RawCDPAdapterError("sealed thumbnail path is missing")
        result = self.runner.run(
            "THUMBNAIL_DISPATCH",
            CHANNEL_ID=remote_channel_id,
            VIDEO_ID=remote_video_id,
            THUMBNAIL_PATH=package.thumbnail_path,
        )
        if result.get("state") != "THUMBNAIL_DISPATCHED":
            raise RawCDPAdapterError(str(result.get("state") or "thumbnail dispatch stopped"))


